#include "batman-routing-protocol.h"
#include "ns3/log.h"
#include "ns3/uinteger.h"
#include "ns3/nstime.h"
#include "ns3/udp-socket-factory.h"
#include "ns3/inet-socket-address.h"
#include "ns3/ipv4-route.h"
#include "ns3/node.h"
#include "ns3/simulator.h"
#include <limits>
namespace ns3 { namespace batman {
NS_LOG_COMPONENT_DEFINE("BatmanRoutingProtocol"); NS_OBJECT_ENSURE_REGISTERED(RoutingProtocol);
TypeId RoutingProtocol::GetTypeId() {
 static TypeId tid=TypeId("ns3::batman::RoutingProtocol").SetParent<Ipv4RoutingProtocol>().SetGroupName("Internet").AddConstructor<RoutingProtocol>()
 .AddAttribute("OgmInterval","Interval between originator messages.",TimeValue(MilliSeconds(500)),MakeTimeAccessor(&RoutingProtocol::m_ogmInterval),MakeTimeChecker(MilliSeconds(10)))
 .AddAttribute("RouteTimeout","Lifetime of learned routes.",TimeValue(Seconds(3)),MakeTimeAccessor(&RoutingProtocol::m_routeTimeout),MakeTimeChecker(MilliSeconds(100)))
 .AddAttribute("Port","UDP port for experimental OGMs.",UintegerValue(269),MakeUintegerAccessor(&RoutingProtocol::m_port),MakeUintegerChecker<uint32_t>(1,65535))
 .AddAttribute("Ttl","Initial OGM time-to-live.",UintegerValue(50),MakeUintegerAccessor(&RoutingProtocol::m_ttl),MakeUintegerChecker<uint8_t>(1,255)); return tid;
}
RoutingProtocol::RoutingProtocol():m_ogmInterval(MilliSeconds(500)),m_routeTimeout(Seconds(3)),m_port(269),m_sequence(0),m_ttl(50),m_running(false),m_jitter(CreateObject<UniformRandomVariable>()){}
RoutingProtocol::~RoutingProtocol(){m_ogmEvent.Cancel();m_expireEvent.Cancel();for(auto& x:m_sockets){x.second.socket->SetRecvCallback(MakeNullCallback<void,Ptr<Socket>>());x.second.socket->Close();}}
void RoutingProtocol::SetIpv4(Ptr<Ipv4> ipv4){NS_ASSERT(ipv4);NS_ASSERT(!m_ipv4);m_ipv4=ipv4;for(uint32_t i=1;i<m_ipv4->GetNInterfaces();++i)if(m_ipv4->IsUp(i))EnsureSocket(i);if(!m_running){m_running=true;m_ogmEvent=Simulator::Schedule(MilliSeconds(50)+Seconds(m_jitter->GetValue(0.0,0.05)),&RoutingProtocol::SendOgm,this);m_expireEvent=Simulator::Schedule(m_ogmInterval,&RoutingProtocol::Expire,this);}}
void RoutingProtocol::EnsureSocket(uint32_t i){if(!m_ipv4||i==0||i>=m_ipv4->GetNInterfaces()||!m_ipv4->IsUp(i)||m_sockets.count(i))return;for(uint32_t a=0;a<m_ipv4->GetNAddresses(i);++a){auto addr=m_ipv4->GetAddress(i,a);if(addr.GetLocal()==Ipv4Address::GetLoopback()||addr.GetLocal()==Ipv4Address::GetZero())continue;Ptr<Socket>s=Socket::CreateSocket(m_ipv4->GetObject<Node>(),UdpSocketFactory::GetTypeId());s->SetAllowBroadcast(true);s->BindToNetDevice(m_ipv4->GetNetDevice(i));if(s->Bind(InetSocketAddress(Ipv4Address::GetAny(),m_port))!=0){s->Close();continue;}s->SetRecvCallback(MakeCallback(&RoutingProtocol::RecvOgm,this));m_sockets[i]={s,i,addr.GetLocal(),addr.GetBroadcast()};break;}}
void RoutingProtocol::CloseInterface(uint32_t i){auto x=m_sockets.find(i);if(x!=m_sockets.end()){x->second.socket->SetRecvCallback(MakeNullCallback<void,Ptr<Socket>>());x->second.socket->Close();m_sockets.erase(x);}for(auto r=m_routes.begin();r!=m_routes.end();)if(r->second.interface==i)r=m_routes.erase(r);else ++r;}
void RoutingProtocol::NotifyInterfaceUp(uint32_t i){EnsureSocket(i);} void RoutingProtocol::NotifyInterfaceDown(uint32_t i){CloseInterface(i);}
void RoutingProtocol::NotifyAddAddress(uint32_t i,Ipv4InterfaceAddress){EnsureSocket(i);} void RoutingProtocol::NotifyRemoveAddress(uint32_t i,Ipv4InterfaceAddress){CloseInterface(i);EnsureSocket(i);}
bool RoutingProtocol::Newer(uint32_t a,uint32_t b)const{return static_cast<int32_t>(a-b)>0;}
void RoutingProtocol::SendOn(const Iface& f,const BatmanHeader& h){Ptr<Packet>p=Create<Packet>();p->AddHeader(h);if(f.socket->SendTo(p,0,InetSocketAddress(f.broadcast,m_port))<0)NS_LOG_DEBUG("OGM send failed on "<<f.local);}
void RoutingProtocol::SendOgm(){if(!m_running)return;if(!m_sockets.empty()){const Iface& origin=m_sockets.begin()->second;BatmanHeader h;h.SetOriginator(origin.local);h.SetSequence(++m_sequence);h.SetTq(255);h.SetTtl(m_ttl);m_seen.insert({h.GetOriginator(),h.GetSequence()});for(const auto& x:m_sockets)SendOn(x.second,h);}Time jitter=Seconds(m_jitter->GetValue(0.0,m_ogmInterval.GetSeconds()*0.1));m_ogmEvent=Simulator::Schedule(m_ogmInterval+jitter,&RoutingProtocol::SendOgm,this);}
void RoutingProtocol::RecvOgm(Ptr<Socket>s){Address from;Ptr<Packet>p;while((p=s->RecvFrom(from))){if(!InetSocketAddress::IsMatchingType(from)||p->GetSize()<BatmanHeader().GetSerializedSize())continue;auto sender=InetSocketAddress::ConvertFrom(from);BatmanHeader h;p->RemoveHeader(h);if(h.GetType()!=BatmanHeader::OGM||h.GetOriginator()==Ipv4Address::GetZero()||h.GetTtl()==0)continue;auto key=std::make_pair(h.GetOriginator(),h.GetSequence());if(m_seen.count(key))continue;m_seen.insert(key);uint32_t in=std::numeric_limits<uint32_t>::max();for(const auto& x:m_sockets)if(x.second.socket==s)in=x.first;if(in==std::numeric_limits<uint32_t>::max())continue;
 if(h.GetOriginator()!=sender.GetIpv4()){auto r=m_routes.find(h.GetOriginator());bool replace=r==m_routes.end();if(!replace)replace=Newer(h.GetSequence(),r->second.sequence)||(h.GetSequence()==r->second.sequence&&h.GetTq()>r->second.tq);if(replace)m_routes[h.GetOriginator()]={sender.GetIpv4(),in,h.GetTq(),h.GetSequence(),Simulator::Now()};}
 if(h.GetTtl()>1){h.SetTtl(h.GetTtl()-1);for(const auto& x:m_sockets)SendOn(x.second,h);}
 }}
void RoutingProtocol::Expire(){Time now=Simulator::Now();for(auto i=m_routes.begin();i!=m_routes.end();)if(now-i->second.updated>m_routeTimeout)i=m_routes.erase(i);else ++i;if(m_seen.size()>8192)m_seen.clear();m_expireEvent=Simulator::Schedule(m_ogmInterval,&RoutingProtocol::Expire,this);}
Ptr<Ipv4Route> RoutingProtocol::MakeRoute(Ipv4Address dst,Ipv4Address hop,uint32_t i)const{if(!m_ipv4||i>=m_ipv4->GetNInterfaces()||m_ipv4->GetNAddresses(i)==0)return nullptr;Ptr<Ipv4Route>r=Create<Ipv4Route>();r->SetDestination(dst);r->SetGateway(hop);r->SetOutputDevice(m_ipv4->GetNetDevice(i));r->SetSource(m_ipv4->GetAddress(i,0).GetLocal());return r;}
Ptr<Ipv4Route> RoutingProtocol::RouteOutput(Ptr<Packet>,const Ipv4Header& h,Ptr<NetDevice> out,Socket::SocketErrno& err){if(!m_ipv4){err=Socket::ERROR_NOROUTETOHOST;return nullptr;}auto r=m_routes.find(h.GetDestination());if(r!=m_routes.end()&&(!out||out==m_ipv4->GetNetDevice(r->second.interface))){err=Socket::ERROR_NOTERROR;return MakeRoute(h.GetDestination(),r->second.nextHop,r->second.interface);}for(uint32_t i=1;i<m_ipv4->GetNInterfaces();++i){if(!m_ipv4->IsUp(i)||(out&&out!=m_ipv4->GetNetDevice(i)))continue;for(uint32_t a=0;a<m_ipv4->GetNAddresses(i);++a){auto addr=m_ipv4->GetAddress(i,a);if(addr.GetMask().IsMatch(addr.GetLocal(),h.GetDestination())){err=Socket::ERROR_NOTERROR;return MakeRoute(h.GetDestination(),h.GetDestination(),i);}}}err=Socket::ERROR_NOROUTETOHOST;return nullptr;}
bool RoutingProtocol::RouteInput(Ptr<const Packet> p,const Ipv4Header& h,Ptr<const NetDevice> in,const UnicastForwardCallback& ucb,const MulticastForwardCallback&,const LocalDeliverCallback& lcb,const ErrorCallback& ecb){if(!m_ipv4)return false;int32_t input=m_ipv4->GetInterfaceForDevice(in);if(input>=0&&m_ipv4->IsDestinationAddress(h.GetDestination(),static_cast<uint32_t>(input))){lcb(p,h,static_cast<uint32_t>(input));return true;}auto r=m_routes.find(h.GetDestination());if(r!=m_routes.end()){auto route=MakeRoute(h.GetDestination(),r->second.nextHop,r->second.interface);if(route){ucb(route,p,h);return true;}}for(uint32_t i=1;i<m_ipv4->GetNInterfaces();++i){if(!m_ipv4->IsUp(i))continue;for(uint32_t a=0;a<m_ipv4->GetNAddresses(i);++a){auto addr=m_ipv4->GetAddress(i,a);if(addr.GetMask().IsMatch(addr.GetLocal(),h.GetDestination())){ucb(MakeRoute(h.GetDestination(),h.GetDestination(),i),p,h);return true;}}}ecb(p,h,Socket::ERROR_NOROUTETOHOST);return true;}
void RoutingProtocol::PrintRoutingTable(Ptr<OutputStreamWrapper>s,Time::Unit unit)const{auto os=s->GetStream();*os<<"BATMAN-inspired routing table at "<<Simulator::Now().As(unit)<<"\nDestination\tNextHop\tIf\tTQ\tAge\n";for(const auto&x:m_routes)*os<<x.first<<'\t'<<x.second.nextHop<<'\t'<<x.second.interface<<'\t'<<unsigned(x.second.tq)<<'\t'<<(Simulator::Now()-x.second.updated).As(unit)<<'\n';}
}}
